params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
$wt='C:\Users\Xxkan\HeavenWorktrees\hcp-indexing-55b8536'
if (Test-Path $wt) { throw "verification worktree already exists: $wt" }
git -C $repo fetch --quiet origin agent/hcp-indexing-20260929-0746
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
git -C $repo worktree add --detach $wt 55b8536633ac1e99acc63139c825c34f3ee1dfff
if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
try {
  python -m py_compile "$wt\heaven-bridge\worker.py" "$wt\heaven-bridge\test_worker.py" "$wt\heaven-bridge\tests\test_worker.py"
  if ($LASTEXITCODE -ne 0) { throw 'py_compile failed' }
  python -m compileall -q "$wt\plugins\heaven-control-plane\heaven_control_plane" "$wt\plugins\heaven-control-plane\tests" "$wt\plugins\heaven-control-plane\verify.py"
  if ($LASTEXITCODE -ne 0) { throw 'compileall failed' }
  python "$wt\heaven-bridge\test_worker.py"
  if ($LASTEXITCODE -ne 0) { throw 'primary bridge regressions failed' }
  python "$wt\heaven-bridge\tests\test_worker.py"
  if ($LASTEXITCODE -ne 0) { throw 'bridge compatibility regressions failed' }
  python "$wt\plugins\heaven-control-plane\verify.py"
  if ($LASTEXITCODE -ne 0) { throw 'control-plane verify failed' }
  git -C $wt diff --check HEAD^ HEAD
  if ($LASTEXITCODE -ne 0) { throw 'commit whitespace check failed' }
  [pscustomobject]@{head=(git -C $wt rev-parse HEAD).Trim();parent=(git -C $wt rev-parse HEAD^).Trim();gate='pass'} | ConvertTo-Json -Compress
} finally {
  git -C $repo worktree remove --force $wt
}
